package com.kaymlyn.planeteater.vehicles;

import com.kaymlyn.planeteater.celestial.Star;
import com.kaymlyn.planeteater.resources.Material;
import lombok.Getter;
import lombok.Setter;

import com.kaymlyn.planeteater.resources.Composition;

/**
 * Specialized equipment for extracting materials from stars
 * Uses magnetic fields and plasma containment technology
 * Must operate at safe distances from the star
 *
 * Generated by Claude (Sonnet 4.5)
 */
@Getter
@Setter
public class StellarHarvester {

    public enum HarvesterType {
        STELLAR_LIFT,       // Magnetic field lifting of corona material
        SOLAR_WIND_SCOOP,   // Captures material from solar wind
        MASS_STREAM         // Advanced: creates artificial mass streams
    }

    private String id;
    private HarvesterType type;
    private double extractionRate;      // kg/s of material extraction
    private double operatingDistance;   // Minimum safe distance from star (meters)
    private double powerRequirement;    // Energy needed (watts)
    private double maxTemperature;      // Maximum temperature it can withstand (K)
    private Composition construction;   // Materials to build it
    private HarvesterState state;

    public enum HarvesterState {
        IDLE,
        DEPLOYING,
        HARVESTING,
        MAINTENANCE
    }

    public StellarHarvester(String id, HarvesterType type, double extractionRate,
                            double operatingDistance, double powerRequirement,
                            double maxTemperature) {
        this.id = id;
        this.type = type;
        this.extractionRate = extractionRate;
        this.operatingDistance = operatingDistance;
        this.powerRequirement = powerRequirement;
        this.maxTemperature = maxTemperature;
        this.construction = new Composition();
        this.state = HarvesterState.IDLE;
    }

    /**
     * Create a basic stellar lift harvester
     * Uses magnetic fields to extract corona material
     */
    public static StellarHarvester createBasicStellarLift(String id) {
        StellarHarvester harvester = new StellarHarvester(
                id,
                HarvesterType.STELLAR_LIFT,
                1e6,        // 1 million kg/s extraction rate
                2.5e9,      // 2.5 million km from star
                1e15,       // 1 petawatt power requirement
                10000.0     // Can withstand 10,000 K
        );

        // Construction materials - needs heat-resistant and magnetic materials
        harvester.construction.addMaterial(Material.TITANIUM, 1e8);        // 100,000 tons
        harvester.construction.addMaterial(Material.IRON, 5e8);            // 500,000 tons (magnetic)
        harvester.construction.addMaterial(Material.ALUMINUM_OXIDE, 1e8);  // Heat shielding
        harvester.construction.addMaterial(Material.SILICA, 5e7);          // Radiation shielding

        return harvester;
    }

    /**
     * Create a solar wind scoop
     * Passively captures material from solar wind
     */
    public static StellarHarvester createSolarWindScoop(String id) {
        StellarHarvester harvester = new StellarHarvester(
                id,
                HarvesterType.SOLAR_WIND_SCOOP,
                1e5,        // 100,000 kg/s (lower rate, but passive)
                5e9,        // 5 million km from star (farther out)
                1e12,       // 1 terawatt (lower power)
                5000.0      // Can withstand 5,000 K
        );

        // Lighter construction - mostly collection surface
        harvester.construction.addMaterial(Material.ALUMINUM, 5e7);        // 50,000 tons
        harvester.construction.addMaterial(Material.TITANIUM, 2e7);        // 20,000 tons
        harvester.construction.addMaterial(Material.SILICA, 1e7);          // Shielding

        return harvester;
    }

    /**
     * Create an advanced mass stream harvester
     * Can create artificial stellar ejections for higher yield
     */
    public static StellarHarvester createMassStreamHarvester(String id) {
        StellarHarvester harvester = new StellarHarvester(
                id,
                HarvesterType.MASS_STREAM,
                1e7,        // 10 million kg/s (very high rate)
                2e9,        // 2 million km from star
                1e16,       // 10 petawatts (enormous power)
                15000.0     // Can withstand 15,000 K
        );

        // Heavy construction with advanced materials
        harvester.construction.addMaterial(Material.TITANIUM, 5e8);        // 500,000 tons
        harvester.construction.addMaterial(Material.IRON, 1e9);            // 1 million tons
        harvester.construction.addMaterial(Material.ALUMINUM_OXIDE, 3e8);  // Advanced shielding
        harvester.construction.addMaterial(Material.CHROMIUM, 1e8);        // Heat resistance
        harvester.construction.addMaterial(Material.NICKEL, 2e8);          // Structural

        return harvester;
    }

    /**
     * Check if this harvester can safely operate at a given distance from a star
     */
    public boolean canOperateAtDistance(double distance, Star star) {
        // Must be beyond minimum safe distance
        if (distance < operatingDistance) {
            return false;
        }

        // Must be beyond star's minimum mining distance
        if (distance < star.getMinimumMiningDistance()) {
            return false;
        }

        // Check temperature constraints (rough approximation)
        // Temperature decreases with square of distance
        double starRadius = 6.96e8; // Sun radius in meters
        double approximateTemp = star.getSurfaceTemperature() *
                Math.pow(starRadius / distance, 2);

        return approximateTemp <= maxTemperature;
    }

    /**
     * Calculate actual extraction rate accounting for distance efficiency
     * Efficiency decreases with distance
     */
    public double getEffectiveExtractionRate(double distance) {
        // Base efficiency at optimal distance
        double optimalDistance = operatingDistance;

        if (distance < optimalDistance) {
            // Too close - reduced efficiency due to heat/radiation
            return extractionRate * 0.5;
        }

        // Efficiency falls off with square of distance beyond optimal
        double distanceRatio = optimalDistance / distance;
        double efficiency = Math.min(1.0, Math.pow(distanceRatio, 2));

        return extractionRate * efficiency;
    }

    /**
     * Perform stellar harvesting operation
     */
    public double harvest(Star star, Material material, double duration, double distance) {
        if (!canOperateAtDistance(distance, star)) {
            return 0.0;
        }

        if (state != HarvesterState.HARVESTING && state != HarvesterState.IDLE) {
            return 0.0;
        }

        state = HarvesterState.HARVESTING;
        double effectiveRate = getEffectiveExtractionRate(distance);
        double requestedAmount = effectiveRate * duration;

        return star.extractStellarMaterial(material, requestedAmount, effectiveRate, duration);
    }

    /**
     * Recycle the harvester for materials
     */
    public Composition recycle() {
        Composition materials = new Composition();
        for (var entry : construction.getMaterials().entrySet()) {
            materials.addMaterial(entry.getKey(), entry.getValue());
        }
        return materials;
    }

    @Override
    public String toString() {
        return String.format("StellarHarvester[id=%s, type=%s, rate=%.3e kg/s, " +
                        "distance=%.3e m, power=%.3e W, state=%s]",
                id, type, extractionRate, operatingDistance, powerRequirement, state);
    }
}
